    def export_midline_edge_metrics(self, base_name, metrics_dir):
        import os, json, numpy as np, pandas as pd, matplotlib.pyplot as plt

        rows = []
        atomic = self._metric_atomic() or {}
        combined = self._metric_combined() or {}
        members_in_combined = {str(m) for cmb in combined.values() for m in (cmb.get("members", []) or [])}

        # only atomics NOT in a combined (to avoid double counting)
        for cid in sorted(atomic.keys(), key=lambda z: int(z)):
            scid = str(cid)
            if scid in members_in_combined:
                continue
            path = os.path.join(self.save_folder, "metrics", base_name, f"cid{scid}.json")
            if not os.path.exists(path): 
                continue
            try:
                with open(path, "r", encoding="utf-8") as f:
                    data = json.load(f)
            except Exception:
                continue
            if not isinstance(data, dict): 
                continue

            row = {
                "image": base_name,
                "crack_type": "atomic",
                "crack_id": scid,
                "win": data.get("window_half_size"),
                "mu": data.get("mu"),
                "l": data.get("l"),
                "p": data.get("p"),
                "chamfer_mean": data.get("chamfer_mean"),
                "hausdorff": data.get("hausdorff"),
                "angle_err_deg": data.get("angle_err_deg"),
                "coverage": data.get("coverage"),
                "directional_bias": data.get("directional_bias"),
                "curvature_rms_ratio": data.get("curvature_rms_ratio"),
                "local_thickness_corr": data.get("local_thickness_corr"),
            }
            rows.append(row)

        if not rows:
            return

        df = pd.DataFrame(rows)
        out_csv = os.path.join(metrics_dir, f"{base_name}_midline_edge_metrics.csv")
        df.to_csv(out_csv, index=False)

        # quick summary by crack_type
        g = df.groupby("crack_type").agg(["mean", "std"])
        out_sum = os.path.join(metrics_dir, f"{base_name}_midline_edge_metrics_summary.csv")
        g.to_csv(out_sum)

        # tiny bar chart of a few key metrics (mean ± std)
        try:
            metrics_pick = ["chamfer_mean", "hausdorff", "angle_err_deg", "coverage"]
            means = df[metrics_pick].mean()
            stds  = df[metrics_pick].std()
            plt.figure(figsize=(7,4), dpi=200)
            x = np.arange(len(metrics_pick))
            plt.bar(x, means.values, yerr=stds.values)
            plt.xticks(x, metrics_pick, rotation=15)
            plt.tight_layout()
            plt.savefig(os.path.join(metrics_dir, f"{base_name}_midline_edge_metrics_barchart.png"), dpi=200)
            plt.close()
        except Exception:
            pass
    
    def compute_mask_and_width_metrics_for_image(self, display=False, export_supervision=False):
        """
        Snapshot-only driver (strict edges). Writes:
        - metrics/<base>/cid{X}/gt_vs_manual_mask_global.png
        - metrics/<base>/cid{X}/gt_normals.png
        - metrics/<base>/combined{C}_{members}/gt_vs_manual_mask_global.png
        - metrics/<base>/combined{C}_{members}/gt_normals.png (merged normals)
        - metrics/<base>/mask_metrics.csv
        - width diff overlays + per-type CSVs
        """
        import os, json, numpy as np, pandas as pd, traceback, cv2
        from helpers.metrics import (
            compute_mask_metrics, boundary_fscore, assd_hd95, reconstruct_manual_mask_from_edges,
            mask_iou, has_valid_mask, manual_mask_from_crack,
            safe_write_json, metric_atomic_path_for, width_summary_to_csv,
            compare_widths_for_cracks, write_width_diff_overlay
        )
        from helpers.combine_debug import _mask_from_crack, auto_groups_from_atomic
        from combiner import build_combined_crack_stateless

        print(f"[DEBUG METRICS] ===== START for {getattr(self, 'name', '?')} =====")
        if getattr(self, "current_mask", None) is None:
            print("[DEBUG METRICS] ⚠ no GT mask loaded")
            return {}

        base_name   = self._image_base()
        metrics_dir = self._metrics_dir()
        os.makedirs(metrics_dir, exist_ok=True)

        ann_path = getattr(self, "ann_name", None)
        if not ann_path or not os.path.exists(ann_path):
            print(f"[DEBUG METRICS] ⚠ no annotation found for {base_name}")
            return {}

        with open(ann_path, "r", encoding="utf-8") as f:
            ann_json = json.load(f)
        authoring_atomic = (ann_json.get("annotations", {}) or {}).get("atomic_cracks", {}) or {}

        H, W = self.original_image.shape[:2]
        gt_full = (self.current_mask > 0).astype(np.uint8)

        # --- merge from snapshots
        atomic = merged_metric_atomic(authoring_atomic, self.save_folder, base_name)
        def _is_manual(cr):
            src = (cr.get("source") or "").lower()
            # adjust this tuple if you have other manual-like sources
            return src in ("manual", "manual_poly")

        atomic_manual = {cid: cr for cid, cr in atomic.items() if _is_manual(cr)}
        print(f"[DEBUG METRICS] using {len(atomic_manual)} manual cracks for mask/width metrics")
        atomic = atomic_manual
        print(f"[DEBUG METRICS] merged {len(atomic)} atomic cracks after edge snapshots merge")

        # --- repair missing crops
        def _bbox_from_mask_full(mask):
            ys, xs = np.where(mask > 0)
            if xs.size == 0 or ys.size == 0:
                return None
            x0, x1 = int(xs.min()), int(xs.max()) + 1
            y0, y1 = int(ys.min()), int(ys.max()) + 1
            return [x0, y0, x1 - x0, y1 - y0]

        repaired = []
        for cid, cr in atomic.items():
            m = _mask_from_crack(cr, H, W)
            if int(m.sum()) == 0:
                m2 = reconstruct_manual_mask_from_edges(cr, H, W)
                if m2 is not None and int(m2.sum()) > 0:
                    bb = _bbox_from_mask_full(m2)
                    if bb:
                        x, y, w, h = bb
                        cr["mask_bbox"] = [x, y, w, h]
                        cr["mask_crop"] = m2[y:y+h, x:x+w].astype("uint8").tolist()
                        safe_write_json(metric_atomic_path_for(self.save_folder, base_name, cid), cr)
                        repaired.append(cid)
        if repaired:
            print(f"[COMBINE_DBG] repaired mask_crop/bbox for: {sorted(repaired)}")

        # --- grouping + rebuild
        authoring_combined = auto_groups_from_atomic(atomic, image_hw=(H, W), px_thresh=10.0)
        print(f"[COMBINE_DBG] synthesized {len(authoring_combined)} combined groups automatically.")

        rebuilt_combined = {}
        for ccid, cmb in authoring_combined.items():
            members = cmb.get("members", []) or []
            if not members:
                continue
            '''rebuilt = build_combined_crack_stateless(
                original_image=self.original_image,
                authoring_atomic=atomic,
                member_ids=[str(m) for m in members],
                window_half_size=45, mu=0.0, l=5, p=14,
                color_channel=0, pad=10, prefer_gpu=True
            )'''
            rebuilt = build_combined_crack_stateless(
                original_image=self.original_image,
                authoring_atomic=atomic,
                member_ids=[str(m) for m in members],
                window_half_size=45, mu=0.0, l=5, p=14,
                color_channel=0, pad=10, prefer_gpu=True,

                # NEW: inline debug callback using metrics helper
                debug_callback=lambda **dbg: metrics_combined_debug_plot(
                    original_image=self.original_image,
                    metrics_dir=metrics_dir,
                    combined_id=ccid,
                    member_ids=members,
                    segs=dbg["segs"],
                    edge1_segs=dbg["edge1"],
                    edge2_segs=dbg["edge2"],
                    norm1_segs=dbg["normals1"],
                    norm2_segs=dbg["normals2"],
                    union_mask=dbg["union_mask"],
                )

            )

            rebuilt["members"] = members
            rebuilt_combined[str(ccid)] = rebuilt
        combined_map = rebuilt_combined

        mask_rows, agg_manual = [], np.zeros((H, W), np.uint8)

        # --- ATOMIC METRICS
        for cid, crack in atomic.items():
            scid = str(cid)
            if scid in [m for g in combined_map.values() for m in (g.get("members") or [])]:
                continue
            try:
                m_full = manual_mask_from_crack(crack, H, W)
                if m_full is None:
                    continue
                agg_manual |= (m_full > 0).astype(np.uint8)
                base = compute_mask_metrics(gt_full, m_full)
                bnd  = boundary_fscore(gt_full, m_full, tau=2.0)
                surf = assd_hd95(gt_full, m_full)
                row = {"image": base_name, "crack_type": "atomic", "crack_id": scid, "members": ""}
                row.update(base); row.update(bnd); row.update(surf)
                mask_rows.append(row)
                print(f"[DEBUG MASK] atomic cid={scid} IoU={base['iou']:.4f}")
            except Exception as e:
                print(f"[atomic fail] {e}")

        # --- COMBINED METRICS (true bbox union for all members) ---
        for ccid, cmb in (combined_map or {}).items():
            try:
                members = cmb.get("members", []) or []
                if not members:
                    continue

                # Build full combined mask (union of member masks)
                combined_mask = np.zeros((H, W), np.uint8)
                member_bboxes = []
                for m in members:
                    cr = atomic.get(str(m))
                    if cr:
                        mm = _mask_from_crack(cr, H, W)
                        combined_mask |= (mm > 0).astype(np.uint8)
                        # store bbox if nonzero
                        if np.any(mm):
                            yx = np.argwhere(mm)
                            y0, x0 = yx.min(axis=0)
                            y1, x1 = yx.max(axis=0)
                            member_bboxes.append([x0, y0, x1, y1])

                if not np.any(combined_mask):
                    print(f"[COMBINE_DBG] ⚠️ combined {ccid} empty mask — skipping.")
                    continue

                # unified bbox across all members
                if member_bboxes:
                    xmins, ymins, xmaxs, ymaxs = zip(*member_bboxes)
                    x0, y0 = max(min(xmins)-5, 0), max(min(ymins)-5, 0)
                    x1, y1 = min(max(xmaxs)+5, W), min(max(ymaxs)+5, H)
                else:
                    x0, y0, x1, y1 = 0, 0, W, H

                # apply crop for metric evaluation
                gt_crop = gt_full[y0:y1, x0:x1]
                man_crop = combined_mask[y0:y1, x0:x1]

                # metrics within true crop
                base = compute_mask_metrics(gt_crop, man_crop)
                bnd  = boundary_fscore(gt_crop, man_crop, tau=2.0)
                surf = assd_hd95(gt_crop, man_crop)

                members_str = "_".join(str(m) for m in members)
                cmb_dir = os.path.join(metrics_dir, f"combined{ccid}_{members_str or 'none'}")
                os.makedirs(cmb_dir, exist_ok=True)

                # Overlay cropped region only
                from helpers.plot_metrics import save_gt_vs_manual_overlay
                save_gt_vs_manual_overlay(
                    H, W, gt_full, combined_mask,
                    os.path.join(cmb_dir, "gt_vs_manual_mask_global.png"),
                    bbox=[x0, y0, x1-x0, y1-y0],
                    original_image=self.original_image,
                )

                # --- build cropped gt_normals ---
                import matplotlib.pyplot as plt
                fig, ax = plt.subplots(figsize=((x1-x0)/100, (y1-y0)/100), dpi=160)
                ax.imshow(combined_mask[y0:y1, x0:x1]*255, cmap="gray", origin="upper",
                        extent=[x0, x1, y1, y0])

                for m in members:
                    cr = atomic.get(str(m))
                    if not cr:
                        continue
                    ml = np.asarray(cr.get("midline", []), float)
                    if ml.ndim == 2 and len(ml) > 1:
                        ax.plot(ml[:, 0], ml[:, 1], "r-", lw=1)
                    ge = cr.get("geodesic_edges", {}) or {}
                    for k, v in ge.items():
                        v = np.asarray(v, float)
                        if v.ndim == 2 and len(v) > 1:
                            ax.plot(v[:, 0], v[:, 1], color="cyan", lw=0.5)
                ax.set_xlim(x0, x1)
                ax.set_ylim(y1, y0)
                ax.axis("off")
                plt.tight_layout(pad=0)
                plt.savefig(os.path.join(cmb_dir, "gt_normals.png"),
                            bbox_inches="tight", pad_inches=0)
                plt.close(fig)

                # record metrics
                row = {
                    "image": base_name,
                    "crack_type": "combined",
                    "crack_id": str(ccid),
                    "members": members_str,
                    **base, **bnd, **surf,
                }
                mask_rows.append(row)
                print(f"[DEBUG MASK] combined id={ccid}({members_str}) IoU={base['iou']:.4f} bF1={bnd['boundary_f1']:.4f}")

                # accumulate into total union
                agg_manual |= (combined_mask > 0).astype(np.uint8)

            except Exception as e:
                print(f"[DEBUG METRICS] combined id={ccid} failed: {e}")
                traceback.print_exc()

        # --- TOTAL
        base_total = compute_mask_metrics(gt_full, agg_manual)
        bnd_total  = boundary_fscore(gt_full, agg_manual, tau=2.0)
        surf_total = assd_hd95(gt_full, agg_manual)
        mask_rows.append({"image": base_name,"crack_type":"TOTAL","crack_id":"","members":"",
                        **base_total,**bnd_total,**surf_total})
        out_csv = os.path.join(metrics_dir,"mask_metrics.csv")
        pd.DataFrame(mask_rows).to_csv(out_csv,index=False)
        print(f"[DEBUG MASK] TOTAL IoU={mask_iou(agg_manual,gt_full):.4f}")

        # === RESTORE WIDTH DIFF CHARTS ===
        try:
            print("[DEBUG METRICS] width comparisons ...")
            width_rows_manual=[]
            ret = compare_widths_for_cracks({"atomic_cracks": atomic}, gt_full, base_name, metrics_dir,
                                            display=display, tag="manual", return_normals=False, normals_plot=False)
            if len(ret): width_rows_manual = ret[0]
            width_summary_to_csv(metrics_dir, base_name, width_rows_manual,"manual")
            write_width_diff_overlay(H,W,width_rows_manual,
                                    os.path.join(metrics_dir,"manual_width_diffs_overlay.png"),vlim=8.0)
            
            # --- Build synthetic per-combined cracks with merged midline + edges ---
            combined_for_width = {}
            for ccid, cmb in combined_map.items():
                members = cmb.get("members", [])
                mid_all, e1_all, e2_all = [], [], []
                for m in members:
                    cr = atomic.get(str(m))
                    if not cr:
                        continue
                    ml = np.asarray(cr.get("midline", []), float)
                    if ml.ndim == 2 and len(ml) >= 2:
                        mid_all.append(ml)
                    ge = cr.get("geodesic_edges", {}) or {}
                    if "edge1" in ge and "edge2" in ge:
                        e1_all.append(np.asarray(ge["edge1"], float))
                        e2_all.append(np.asarray(ge["edge2"], float))
                if mid_all:
                    mid_merge = np.vstack(mid_all)
                else:
                    mid_merge = np.zeros((0, 2))
                e1_merge = np.vstack(e1_all) if e1_all else np.zeros((0, 2))
                e2_merge = np.vstack(e2_all) if e2_all else np.zeros((0, 2))

                combined_for_width[str(ccid)] = {
                    "midline": mid_merge.tolist(),
                    "geodesic_edges": {"edge1": e1_merge.tolist(), "edge2": e2_merge.tolist()},
                    "members": members,
                }

            # --- now run comparison using the synthetic set
            retc = compare_widths_for_cracks({"atomic_cracks": combined_for_width},
                                            gt_full, base_name, metrics_dir,
                                            display=display, tag="combined",
                                            return_normals=False, normals_plot=False)

            
            # Combined width diffs
            #retc = compare_widths_for_cracks({"atomic_cracks": combined_map}, gt_full, base_name, metrics_dir,
            #                                display=display, tag="combined", return_normals=False, normals_plot=False)
            if len(retc):
                width_summary_to_csv(metrics_dir, base_name, retc[0], "combined")
                write_width_diff_overlay(H, W, retc[0],
                                        os.path.join(metrics_dir, "combined_width_diffs_overlay.png"), vlim=8.0)
        except Exception as e:
            print(f"[DEBUG WIDTH] failed: {e}")
            
        # === FINAL SUMMARY / PRESENTATION PLOTS ===
        try:
            from helpers.present_plots import build_deck_plots_for_image
            print("[DEBUG PLOT] building deck-ready summary plots ...")
            build_deck_plots_for_image(metrics_dir, base_name)
        except Exception as e:
            print(f"[DEBUG PLOT] deck plots failed: {e}")

        print(f"[DEBUG METRICS] ===== END for {base_name} =====")
    
    # ===============================================================
    # === Smoke test edge worker (cropped + light aware) ===
    # ===============================================================
    def smoke_test_edges_for_manual(self, crack_id, edge_params=None, color_channel=None):
        import os, numpy as np, traceback, cv2
        from edge_workers import edge_param_worker, _debug_plot_edge_worker
        #from helpers.metrics import (
        #    metric_atomic_path_for, safe_read_json,
        #    set_tracked_edges_for_crack, metric_image_dir
        #)
        base = self._image_base()
        p = metric_atomic_path_for(self.save_folder, base, crack_id)
        cr = safe_read_json(p, {})
        if not cr:
            print(f"[smoke] ❌ no snapshot for cid={crack_id}")
            return False

        H, W = self.original_image.shape[:2]
        bb = cr.get("mask_bbox", None)
        if not (isinstance(bb, (list, tuple)) and len(bb) == 4):
            print(f"[smoke] ❌ cid{crack_id}: invalid mask_bbox {bb}")
            return False
        x, y, w, h = map(int, bb)
        xmin, ymin, xmax, ymax = x, y, x + w, y + h
        man_xy_g = np.asarray(cr.get("midline", []), float)

        try:
            self.active_bbox = [xmin, ymin, xmax, ymax]
            self.pts = [man_xy_g[0].copy(), man_xy_g[-1].copy()]
            self.end_points = self.pts
            self.update_image_crop()
            if getattr(self, "skip_current_segment", False):
                return False
        except Exception as e:
            traceback.print_exc()
            return False

        if color_channel is None:
            color_channel = (0 if self.edge_track_color_box.currentText()=="R"
                            else 1 if self.edge_track_color_box.currentText()=="B"
                            else 2)
        gray = self.image_crop[:, :, color_channel].astype(np.float32)
        track_local_yx = np.vstack([man_xy_g[:,1]-ymin, man_xy_g[:,0]-xmin])
        if edge_params is None:
            edge_params = {"window_half_size":45, "mu":0.0, "l":5, "p":14}

        gt_crop = None
        if getattr(self, "current_mask", None) is not None:
            gt_crop = ((self.current_mask[y:y+h, x:x+w]) > 0).astype(np.uint8)

        payload = dict(
            image_crop_gray=gray,
            pts_crop=self.pts_crop,
            adjusted_track=track_local_yx,
            manual_midline_global=man_xy_g,
            bbox=(x, y, w, h),
            params=edge_params,
            save_folder=self.save_folder,
            image_base=base,
            crack_id=str(crack_id),
            gt_crop=gt_crop,
        )

        ew = edge_param_worker(payload)
        if not isinstance(ew, dict):
            print(f"[smoke] ❌ edge worker returned empty for cid{crack_id}")
            return False

        set_tracked_edges_for_crack(self.save_folder, base, crack_id, ew, mask_crop=ew.get("mask_crop"))
        cid_path = os.path.join(self.save_folder, "metrics", base, f"cid{crack_id}.json")
        if os.path.exists(cid_path):
            print(f"[smoke] ✅ found snapshot {cid_path}")
        else:
            print(f"[smoke] ❌ expected cid file not found at {cid_path}")

        if not DEBUG_SAVE_LIGHT:
            # old heavy overlays only when full debug enabled
            try:
                e1 = np.array(ew.get("geodesic_edges", {}).get("edge1", []), float)
                e2 = np.array(ew.get("geodesic_edges", {}).get("edge2", []), float)
                _debug_plot_edge_worker(
                    gray, np.zeros_like(gray), np.zeros_like(gray),
                    np.column_stack([track_local_yx[1], track_local_yx[0]]),
                    e1, e2, edge_params, tag=f"cid{crack_id}_smoke",
                )
                print(f"[smoke] wrote edge-worker debug plot for cid{crack_id}")
            except Exception as e:
                print(f"[smoke] overlay(local) failed: {e}")

            try:
                ge = cr.get("geodesic_edges", {})
                overlay = self.original_image.copy()
                if overlay.ndim == 2:
                    overlay = cv2.cvtColor(overlay, cv2.COLOR_GRAY2BGR)
                for key, arr in ge.items():
                    arr = np.array(arr, float)
                    if arr.ndim == 2 and len(arr) >= 2:
                        color = (0, 0, 255) if "edge1" in key else (0, 255, 0)
                        cv2.polylines(overlay, [arr.astype(np.int32)], False, color, 1, lineType=cv2.LINE_AA)
                save_dir = os.path.join(self.save_folder, "debug_outputs")
                os.makedirs(save_dir, exist_ok=True)
                out_path = os.path.join(save_dir, f"{base}_cid{crack_id}_edges_overlay.png")
                cv2.imwrite(out_path, overlay)
            except Exception as e:
                print(f"[smoke] overlay(full) failed: {e}")

        print(f"[smoke] ✅ edges ok for cid{crack_id}")
        return True
    
    def smoke_test_edges_for_combined(self, ccid: int, cmb: dict, edge_params=None, color_channel=None):
        import os, numpy as np, cv2
        from edge_workers import edge_param_worker
        from helpers.save_load_files import safe_read_json, safe_write_json, metric_combined_path

        base = self._image_base()
        H, W = self.original_image.shape[:2]
        ml = np.asarray(cmb.get("midline", []), float)
        if ml.ndim != 2 or len(ml) < 2:
            return False

        # bbox
        bbox = cmb.get("mask_bbox")
        if not bbox:
            m_full = manual_mask_from_crack(cmb, H, W)
            bbox = plot_metrics.bbox_from_mask(m_full) or [0,0,W,H]
        x,y,w,h = map(int, bbox)

        if color_channel is None:
            color_channel = 0 if self.edge_track_color_box.currentText()=="R" else 1 if self.edge_track_color_box.currentText()=="B" else 2
        gray = self.original_image[:, :, color_channel].astype(np.float32)
        crop = gray[y:y+h, x:x+w]
        track_local_yx = np.vstack([ml[:,1]-y, ml[:,0]-x])

        payload = dict(
            image_crop_gray=crop,
            pts_crop=[ml[0]-[x,y], ml[-1]-[x,y]],
            adjusted_track=track_local_yx,
            manual_midline_global=ml,
            bbox=(x,y,w,h),
            params=edge_params or {"window_half_size":45, "mu":0.0, "l":5, "p":14},
            save_folder=self.save_folder,
            image_base=base,
            crack_id=f"combined{ccid}",
            gt_crop=((self.current_mask[y:y+h, x:x+w]) > 0).astype(np.uint8) if getattr(self,"current_mask",None) is not None else None,
        )

        res = edge_param_worker(payload)
        if not isinstance(res, dict) or res.get("status")!="ok":
            return False

        # persist to combined.json
        cpath = metric_combined_path(self.save_folder, base)
        cdata = safe_read_json(cpath, {}) or {}
        rec = cdata.get(str(ccid), {})
        rec["geodesic_edges"] = res.get("geodesic_edges", {})
        rec["mask_crop"] = res.get("mask_crop", None)
        rec["mask_bbox"] = [x,y,w,h]
        cdata[str(ccid)] = rec
        safe_write_json(cpath, cdata)
        return True
        
    def run_midline_and_mask_metrics(self, tau_px=3.0, crack_id=None, display=True, do_param_sweep=True):
        """
        Minimal smoke test for manual cracks.
        Uses helpers.metrics for all real computations.
        Just fixes:
        - combined refresh
        - per-CID overlay path (no top-level clutter)
        - midline drawn on gt_normals
        - total/global summary + midline metrics call
        """
        import os, time, numpy as np, traceback, cv2
        from helpers.metrics import reconstruct_manual_mask_from_edges

        if not getattr(self, "name", None):
            print("[metrics] ⚠ no image loaded — aborting smoke test.")
            return

        base_name = os.path.splitext(os.path.basename(self.name))[0]
        image_dir = os.path.join(self.save_folder, "metrics", base_name)
        os.makedirs(image_dir, exist_ok=True)
        print(f"\n[SMOKE] ===== running minimal metrics for {base_name} =====")
        t_total_start = time.perf_counter()

        # --- 1) refresh combined snapshot ---
        try:
            self._sync_metrics_snapshot_from_authoring(refresh_combine=True, persist=False)
        except Exception as e:
            traceback.print_exc()
            print(f"[SMOKE] snapshot sync failed: {e}")
            return

        # 🔍 ADD THIS ↓↓↓
        print("[DEBUG SNAPSHOT] after sync:")
        try:
            ann_json_path = os.path.join(self.save_folder, f"{base_name}.json")
            print(f"[DEBUG SNAPSHOT] expected annotation path: {ann_json_path}")
            if os.path.exists(ann_json_path):
                with open(ann_json_path, "r") as f:
                    ann_json = json.load(f)
                print(f"[DEBUG SNAPSHOT] top-level keys: {list(ann_json.keys())}")
                anns = ann_json.get("annotations", {})
                print(f"[DEBUG SNAPSHOT] annotations keys: {list(anns.keys())}")
                print(f"[DEBUG SNAPSHOT] combined_cracks len = {len(anns.get('combined_cracks', {}))}")
                print(f"[DEBUG SNAPSHOT] combined len = {len(anns.get('combined', {}))}")
            else:
                print("[DEBUG SNAPSHOT] ❌ no annotation JSON found at path")
        except Exception as e:
            print(f"[DEBUG SNAPSHOT] failed to read JSON: {e}")

        atomic = self._metric_atomic()
        if not atomic:
            print("[SMOKE] ❌ no cracks found in snapshot")
            return

        best_edge = {"window_half_size":45, "mu":0.0, "l":5, "p":14}

        # --- 2) run edge workers where needed ---
        need_ids = []
        for cid, cr in atomic.items():
            src = (cr.get("source") or "").lower()
            if src.startswith("auto") or src == "combined":
                continue
            mid = np.asarray(cr.get("midline", []), float)
            if mid.ndim != 2 or mid.shape[1] != 2 or len(mid) < 2:
                continue
            #ge = cr.get("geodesic_edges", {}) or {}
            #has_e1 = isinstance(ge.get("edge1"), list) and len(ge.get("edge1")) > 1
            #has_e2 = isinstance(ge.get("edge2"), list) and len(ge.get("edge2")) > 1
            #if not (has_e1 and has_e2):
            #    need_ids.append(cid)
            need_ids.append(cid)

        print(f"[SMOKE] manual cracks needing edges: {need_ids}")
        for cid in need_ids:
            try:
                self.smoke_test_edges_for_manual(cid, edge_params=best_edge)
            except Exception as e:
                traceback.print_exc()
                print(f"[SMOKE] ❌ edge smoke failed for cid={cid}: {e}")

        # --- 3) use existing metric pipeline ---
        try:
            print("[SMOKE] running mask/width metrics ...")
            self.compute_mask_and_width_metrics_for_image(display=display, export_supervision=False)
        except Exception as e:
            traceback.print_exc()
            print(f"[SMOKE] mask/width stage failed: {e}")

        # --- 4) move per-CID overlay into its folder + redraw midline on gt_normals ---
        try:
            H, W = self.original_image.shape[:2]
            gt = (self.current_mask > 0).astype(np.uint8) if getattr(self, "current_mask", None) is not None else np.zeros((H, W), np.uint8)
            ann = self._metric_atomic()

            for cid, crack in ann.items():
                src = (crack.get("source") or "").lower()
                if src.startswith("auto") or src == "combined":
                    continue

                m_manual = reconstruct_manual_mask_from_edges(crack, H, W)
                pred_mask = (m_manual > 0).astype(np.uint8)
                gt_mask = gt.copy()

                intersect = np.logical_and(gt_mask, pred_mask)
                pred_only = np.logical_and(pred_mask, np.logical_not(gt_mask))
                gt_only   = np.logical_and(gt_mask, np.logical_not(pred_mask))

                vis = cv2.cvtColor(self.original_image, cv2.COLOR_GRAY2BGR) if self.original_image.ndim == 2 else self.original_image.copy()
                vis = vis.astype(np.float32) / 255.0
                overlay = np.zeros_like(vis, np.float32)
                overlay[gt_only]   = (0, 0, 1.0)
                overlay[pred_only] = (0, 1.0, 1.0)
                overlay[intersect] = (1.0, 1.0, 1.0)
                blended = cv2.addWeighted(overlay, 0.7, vis, 0.3, 0)
                blended = np.clip(blended * 255.0, 0, 255).astype(np.uint8)

                cid_dir = os.path.join(image_dir, f"cid{cid}")
                os.makedirs(cid_dir, exist_ok=True)
                out_dbg = os.path.join(cid_dir, "debug_mask_overlay.png")
                cv2.imwrite(out_dbg, blended)

                # add midline to gt_normals if it exists
                normals_path = os.path.join(cid_dir, "gt_normals.png")
                if os.path.exists(normals_path):
                    ml = np.asarray(crack.get("midline", []), float)
                    if ml.ndim == 2 and len(ml) > 1:
                        img = cv2.imread(normals_path)
                        cv2.polylines(img, [ml.astype(np.int32)], False, (0,0,255), 1, cv2.LINE_AA)
                        cv2.imwrite(normals_path, img)

                print(f"[SMOKE] wrote mask overlay → {out_dbg}")
        except Exception as e:
            print(f"[SMOKE] overlay debug failed: {e}")

        # --- 5) run existing midline metric CSV (in helpers.metrics) ---
        #try:
        #    compute_midline_metrics_for_image(self)
        #except Exception as e:
        #    print(f"[SMOKE] midline metrics failed: {e}")

        self.dump_global_midline_and_mask_overlays(thickness_px=3)
        total_time = time.perf_counter() - t_total_start
        print(f"[SMOKE] ✅ completed minimal metrics in {total_time:.2f}s\n")
         
    # ================= crack_tool.py (metrics snapshot integration) =================

    # ---- 0) tiny shorthands -------------------------------------------------------
    def _image_base(self):
        import os
        return os.path.splitext(os.path.basename(self.name))[0]

    def _metrics_dir(self):
        import os
        return os.path.join(self.save_folder, "metrics", self._image_base())

    # ---- 1) snapshot lifecycle ----------------------------------------------------
    def _ensure_metric_annotations(self):
        if not hasattr(self, "metric_annotations") or self.metric_annotations is None:
            self.metric_annotations = {"atomic_cracks": {}, "combined_cracks": {}, "auto_best_atomic_cracks": {}}

    def _metrics_compute_fingerprint(self):
        """Fingerprint ONLY of the read-only snapshot."""
        from helpers.metrics import snapshot_fingerprint
        self._ensure_metric_annotations()
        return snapshot_fingerprint(self.metric_annotations)

    def _metrics_state_path(self, base_name):
        import os
        return os.path.join(self.save_folder, "metrics", base_name, "METRICS_STATE.json")

    def _metrics_write_state(self, base_name, payload):
        import json, os, time
        os.makedirs(os.path.join(self.save_folder, "metrics", base_name), exist_ok=True)
        out = dict(payload or {})
        out["image"] = base_name
        out["timestamp"] = time.strftime("%Y-%m-%d %H:%M:%S")
        out["ann_fingerprint"] = self._metrics_compute_fingerprint()
        with open(self._metrics_state_path(base_name), "w", encoding="utf-8") as f:
            json.dump(out, f)

    def metrics_is_fresh_for_current_image(self):
        """True if METRICS_STATE exists & snapshot fingerprint matches → skip."""
        import json, os
        base_name = self._image_base()
        p = self._metrics_state_path(base_name)
        if not os.path.exists(p): return False
        try:
            with open(p, "r", encoding="utf-8") as f: st = json.load(f)
            return st.get("ann_fingerprint") == self._metrics_compute_fingerprint()
        except Exception:
            return False

    def _sync_metrics_snapshot_from_authoring(self, refresh_combine=False, persist=False):
        """
        Build per-crack metric snapshot files from self.annotation (read-only inputs only),
        then load self.metric_annotations from those files.

        Does NOT call any GUI builders or mutate self.annotation.
        Combined cracks are never recomputed here — only membership lists are preserved.
        """
        import os
        from helpers.metrics import snapshot_from_authoring, split_snapshot_to_files, load_snapshot_from_files

        base = self._image_base()
        authoring = (self.annotation or {}).get("annotations", {}) or {}

        # Optional refresh of combined membership structure (no geometry)
        if refresh_combine:
            try:
                ann_atomic = dict(authoring.get("atomic_cracks", {}) or {})
                combined_existing = dict(authoring.get("combined_cracks", {}) or {})
                combined_clean = {}

                for k, cmb in combined_existing.items():
                    # Keep only members that still exist in atomics
                    members = [m for m in cmb.get("members", []) if str(m) in ann_atomic]
                    if not members:
                        continue
                    # Copy only membership info; do NOT rebuild geometry here
                    combined_clean[k] = {"members": members}

                authoring = dict(authoring)
                authoring["combined_cracks"] = combined_clean
            except Exception as e:
                print(f"[metrics/snapshot] ⚠ combined membership refresh failed: {e}")

        # --- Snapshot → Disk ---
        snap = snapshot_from_authoring(authoring, cache_key=None)
        split_snapshot_to_files(snap, self.save_folder, base, merge_if_exists=True)

        # (persist flag kept for compatibility; actual persistence is handled by split_snapshot_to_files)
        if refresh_combine and persist:
            pass

        # --- Reload active working snapshot ---
        self.metric_annotations = load_snapshot_from_files(self.save_folder, base)

    def _metric_atomic(self):
        self._ensure_metric_annotations()
        return self.metric_annotations.get("atomic_cracks", {}) or {}

    def _metric_combined(self):
        self._ensure_metric_annotations()
        return self.metric_annotations.get("combined_cracks", {}) or {}

    def _metric_auto_best(self):
        self._ensure_metric_annotations()
        return self.metric_annotations.get("auto_best_atomic_cracks", {}) or {}

    def _export_supervision_for_image(self, normal_half_span=32.0, step=0.5, precomputed_normals=None):
        """
        Export *one* consolidated supervision CSV per image.

        Columns:
        image, crack_type, crack_id, sample_idx,
        mid_x, mid_y,
        edgeL_x, edgeL_y, edgeR_x, edgeR_y, width_px
        """
        import os, numpy as np, pandas as pd, traceback
        from helpers.metrics import normals_from_mask_for_midline

        base_name = self._image_base()
        print(f"[DEBUG SUP] === EXPORT (UNIFIED) for {base_name} ===")

        if getattr(self, "current_mask", None) is None:
            print("[DEBUG SUP] no GT mask loaded — abort")
            return

        H, W = self.original_image.shape[:2]
        mask_bin = (self.current_mask > 0).astype(np.uint8)

        out_root = os.path.join(self.save_folder, "metrics", base_name, "supervision")
        os.makedirs(out_root, exist_ok=True)

        atomic    = self._metric_atomic() or {}
        combined  = self._metric_combined() or {}
        auto_best = self._metric_auto_best() or {}

        # atomics that were merged → skip to avoid duplicates
        atomics_in_combined = {str(m) for cmb in combined.values() for m in (cmb.get("members", []) or [])}

        def _pack_df(ctype, cid, mid_xy, e1, e2):
            e1 = np.asarray(e1, float); e2 = np.asarray(e2, float); mid_xy = np.asarray(mid_xy, float)
            if e1.ndim != 2 or e2.ndim != 2 or mid_xy.ndim != 2: return None
            if e1.shape[0] < 2 or e2.shape[0] < 2 or mid_xy.shape[0] < 2: return None
            n = min(len(mid_xy), len(e1), len(e2))
            if n < 2: return None
            w = np.hypot(e1[:n,0] - e2[:n,0], e1[:n,1] - e2[:n,1])
            return pd.DataFrame({
                "image": base_name,
                "crack_type": ctype,
                "crack_id": cid,
                "sample_idx": np.arange(n, dtype=int),
                "mid_x": mid_xy[:n,0], "mid_y": mid_xy[:n,1],
                "edgeL_x": e1[:n,0],  "edgeL_y": e1[:n,1],
                "edgeR_x": e2[:n,0],  "edgeR_y": e2[:n,1],
                "width_px": w
            })

        def _process_crack(ctype, cid, crack):
            mid_xy = np.asarray(crack.get("midline", []), float)
            if mid_xy.ndim != 2 or mid_xy.shape[1] != 2 or len(mid_xy) < 2:
                print(f"[DEBUG SUP] skip invalid midline {ctype} {cid}")
                return None

            # 1) try precomputed normals dict if provided
            try:
                if precomputed_normals and (ctype, str(cid)) in precomputed_normals:
                    nd = precomputed_normals[(ctype, str(cid))]
                    e1 = np.asarray(nd.get("gt_e1"))
                    e2 = np.asarray(nd.get("gt_e2"))
                    if e1 is not None and e2 is not None and len(e1) >= 2 and len(e2) >= 2:
                        return _pack_df(ctype, cid, mid_xy, e1, e2)
            except Exception as e:
                print(f"[DEBUG SUP] precomputed normals failed {ctype} {cid}: {e}")
                traceback.print_exc()

            # 2) try auto normals saved on the crack (if present)
            try:
                nd_auto = crack.get("normal_edge_points_full") or crack.get("normal_edge_points")
                if nd_auto:
                    if isinstance(nd_auto, dict):
                        e1 = np.asarray(nd_auto.get("edge1"), float)
                        e2 = np.asarray(nd_auto.get("edge2"), float)
                    else:
                        # legacy local form: [[e1x, e1y], [e2x, e2y]]
                        (e1x, e1y), (e2x, e2y) = nd_auto
                        e1 = np.column_stack([e1x, e1y])
                        e2 = np.column_stack([e2x, e2y])
                    df = _pack_df(ctype, cid, mid_xy, e1, e2)
                    if df is not None:
                        return df
            except Exception as e:
                print(f"[DEBUG SUP] auto normals parse failed {ctype} {cid}: {e}")
                traceback.print_exc()

            # 3) fallback: derive normals from mask along midline
            try:
                (e1x, e1y, e2x, e2y, w_mask), _ = normals_from_mask_for_midline(mid_xy, mask_bin, max_radius=50)
                e1 = np.column_stack([e1x, e1y])
                e2 = np.column_stack([e2x, e2y])
                return _pack_df(ctype, cid, mid_xy, e1, e2)
            except Exception as e:
                print(f"[DEBUG SUP] normals_from_mask_for_midline failed {ctype} {cid}: {e}")
                traceback.print_exc()
                return None

        rows = []

        # atomics (excluding those absorbed into combined)
        print(f"[DEBUG SUP] exporting atomics (excluding {len(atomics_in_combined)} absorbed)")
        for cid, crack in atomic.items():
            if str(cid) in atomics_in_combined: 
                continue
            df = _process_crack("atomic", str(cid), crack)
            if df is not None and not df.empty: rows.append(df)

        # combined
        print(f"[DEBUG SUP] exporting {len(combined)} combined cracks")
        for cid, crack in combined.items():
            df = _process_crack("combined", str(cid), crack)
            if df is not None and not df.empty: rows.append(df)

        if rows:
            df_all = pd.concat(rows, ignore_index=True)
            out_csv = os.path.join(out_root, "supervision_all.csv")
            df_all.to_csv(out_csv, index=False)
            print(f"[DEBUG SUP] wrote {len(df_all)} samples from {len(rows)} cracks → {out_csv}")
        else:
            print(f"[DEBUG SUP] no valid cracks to export for {base_name}")

        print(f"[DEBUG SUP] === END (UNIFIED) for {base_name} ===\n")
       
    # ---- 4) Extract inputs for a subcrack (READS SNAPSHOT ONLY) ------------------
    def extract_edge_inputs_for_subcrack(self, crack_id, color_channel=None):
        """
        Faithful payload builder for edge worker using only the per-crack snapshot file.
        """
        import numpy as np
        from helpers.metrics import metric_atomic_path_for, safe_read_json

        cid = str(crack_id)
        p = metric_atomic_path_for(self.save_folder, self._image_base(), cid)
        ann = safe_read_json(p, {})
        if not ann:
            print(f"[extract_edge_inputs] no snapshot for cid={cid}")
            return None

        x, y, w, h = map(int, ann.get("mask_bbox", [0,0,0,0]))
        if w <= 0 or h <= 0:
            print(f"[extract_edge_inputs] cid{cid} missing/invalid bbox")
            return None
        self.active_bbox = [x, y, x+w, y+h]

        if color_channel is None:
            color_channel = (0 if self.edge_track_color_box.currentText() == "R"
                            else 1 if self.edge_track_color_box.currentText() == "B"
                            else 2)

        man_xy_g = np.asarray(ann.get("midline", []), float)
        if man_xy_g.ndim != 2 or man_xy_g.shape[1] != 2 or len(man_xy_g) < 2:
            print(f"[extract_edge_inputs] ⚠ no valid manual midline for {cid}")
            return None

        # endpoints like pipeline
        self.pts = [np.array(man_xy_g[0]), np.array(man_xy_g[-1])]
        self.end_points = self.pts

        self.update_image_crop()
        if getattr(self, "skip_current_segment", False):
            return None

        # local track [y,x]
        track_local_yx = np.vstack([man_xy_g[:,1] - y, man_xy_g[:,0] - x])

        # flip if needed
        start_xy = track_local_yx[:,0][::-1]
        d0 = np.linalg.norm(start_xy - self.pts_crop[0])
        d1 = np.linalg.norm(start_xy - self.pts_crop[1])
        if d1 < d0:
            track_local_yx = track_local_yx[:, ::-1]

        # manual normals (crop) if saved
        man_normals_crop = None
        ne = ann.get("normal_edge_points_full") or ann.get("normal_edge_points")
        if isinstance(ne, dict):
            e1 = np.asarray(ne.get("edge1", []), float)
            e2 = np.asarray(ne.get("edge2", []), float)
            e1c = np.column_stack([e1[:,0]-x, e1[:,1]-y]) if e1.ndim==2 else np.empty((0,2))
            e2c = np.column_stack([e2[:,0]-x, e2[:,1]-y]) if e2.ndim==2 else np.empty((0,2))
            if len(e1c) and len(e2c):
                man_normals_crop = [[e1c[:,0], e1c[:,1]], [e2c[:,0], e2c[:,1]]]

        gray = self.image_crop[:, :, color_channel].astype(np.float32)

        # clamp
        H, W = gray.shape[:2]
        for p in self.pts_crop:
            p[0] = np.clip(p[0], 0, W-1e-3)
            p[1] = np.clip(p[1], 0, H-1e-3)

        return dict(
            image_crop_gray=gray,
            pts_crop=self.pts_crop,
            adjusted_track=track_local_yx,
            manual_midline_global=man_xy_g,
            auto_midline_global=None,
            bbox=(x, y, w, h),
            manual_normals_crop=man_normals_crop,
        )

    # ---- 5) Edge tracking parallel (SAVE ONLY TO SNAPSHOT FILES) -----------------
    def run_edge_tracking_parallel(self, crack_ids=None, cpu_max_workers=None, edge_params_fixed=None, color_channel=None):
        """
        Parallelize edge-mask + edge-tracking and save results into per-crack files.
        """
        import os, time
        import numpy as np
        import pandas as pd
        from concurrent.futures import ProcessPoolExecutor, as_completed
        from edge_workers import edge_param_worker
        from helpers.metrics import set_tracked_edges_for_crack

        t0 = time.perf_counter()
        self._sync_metrics_snapshot_from_authoring(refresh_combine=False, persist=True)
        atomic = self._metric_atomic()
        if not atomic:
            print("[edge-parallel] ❌ no cracks to process")
            return []

        if crack_ids is None:
            crack_ids = list(atomic.keys())

        if color_channel is None:
            color_channel = (0 if self.edge_track_color_box.currentText() == "R"
                            else 1 if self.edge_track_color_box.currentText() == "B"
                            else 2)
        if edge_params_fixed is None:
            edge_params_fixed = {"window_half_size":45,"mu":0,"l":5,"p":14}
        if cpu_max_workers is None:
            import os as _os
            cpu_max_workers = min(_os.cpu_count() or 8, 12)

        base_name   = self._image_base()
        metrics_dir = self._metrics_dir()
        os.makedirs(metrics_dir, exist_ok=True)

        # Prepare payloads from snapshot files
        tasks = []
        for cid in crack_ids:
            payload = self.extract_edge_inputs_for_subcrack(cid, color_channel=color_channel)
            if payload is None: continue
            p = dict(payload)
            p["params"] = dict(edge_params_fixed)
            tasks.append((cid, p))

        if not tasks:
            print("[edge-parallel] nothing to run")
            return []

        print(f"[edge-parallel] launching {len(tasks)} edge workers across {cpu_max_workers} CPUs…")
        results = []
        with ProcessPoolExecutor(max_workers=cpu_max_workers) as ex:
            futs = {ex.submit(edge_param_worker, payload): cid for cid, payload in tasks}
            for f in as_completed(futs):
                cid = futs[f]
                try:
                    ew = f.result()
                    if isinstance(ew, dict):
                        results.append({"crack_id": cid, **ew})
                        # persist edges/normals to per-crack file
                        set_tracked_edges_for_crack(self.save_folder, base_name, cid, ew, mask_crop=ew.get("mask_crop"))
                        print(f"[edge-parallel] cid{cid} ✅")
                    else:
                        print(f"[edge-parallel] cid{cid} empty")
                except Exception as e:
                    print(f"[edge-parallel] cid{cid} ❌ {e}")

        # summarize to CSV
        t_elapsed = time.perf_counter() - t0
        if results:
            df = pd.DataFrame(results)
            df.to_csv(os.path.join(metrics_dir, "edge_parallel_results.csv"), index=False)
            print(f"[edge-parallel] ✅ finished {len(results)} cracks in {t_elapsed:.2f}s "
                f"({t_elapsed/max(1,len(results)):.2f}s/crack avg)")
        else:
            print(f"[edge-parallel] ⚠ no successful results (elapsed {t_elapsed:.2f}s)")

        # reload snapshot to include newly saved edges
        from helpers.metrics import load_snapshot_from_files
        self.metric_annotations = load_snapshot_from_files(self.save_folder, base_name)
        return results

    # ---------- crack_tool.py (DROP-IN ADDITION inside the class) ----------
        
    def ensure_tracked_edges_and_normals(self, crack_id, edge_params_fixed):
        """
        Guarantees: geodesic_edges + normal_edge_points exist in cid{crack_id}.json.
        Adds deep debug inspection after edge-tracking to pinpoint missing keys.
        """
        import numpy as np, os, json, traceback
        from helpers.metrics import (
            metric_atomic_path_for, safe_read_json, safe_write_json,
            set_geodesic_edges_for_crack, debug_plot_gt_preview
        )
        from helpers.metrics import metric_image_dir

        base = self._image_base()
        p = metric_atomic_path_for(self.save_folder, base, crack_id)
        cr = safe_read_json(p, {})

        print(f"[DEBUG edges] ===== ensure_tracked_edges_and_normals(cid={crack_id}) =====")
        print(f"[DEBUG edges] path: {p}")
        print(f"[DEBUG edges] keys before: {list(cr.keys())}")

        # fast exits if already have what we need
        ge = cr.get("geodesic_edges") or {}
        has_e1 = isinstance(ge.get("edge1"), list) and len(ge.get("edge1")) > 1
        has_e2 = isinstance(ge.get("edge2"), list) and len(ge.get("edge2")) > 1
        has_normals = isinstance(cr.get("normal_edge_points") or cr.get("normal_edge_points_full"), dict)

        print(f"[DEBUG edges] has_e1={has_e1} has_e2={has_e2} has_normals={has_normals}")

        mid = np.asarray(cr.get("midline", []), float)
        if mid.ndim != 2 or mid.shape[1] != 2 or len(mid) < 2:
            print(f"[edges] cid{crack_id}: no midline → skip")
            return False

        # --- Attempt regeneration if missing ---
        if not (has_e1 and has_e2):
            try:
                print(f"[edges] cid{crack_id}: running edge tracking ...")
                _ = self.run_edge_tracking_parallel(
                    crack_ids=[crack_id], cpu_max_workers=1, edge_params_fixed=edge_params_fixed
                )
            except Exception as e:
                print(f"[edges] cid{crack_id}: run_edge_tracking_parallel failed: {e}")
                traceback.print_exc()

            # Reload to inspect updated file
            cr = safe_read_json(p, {})
            print(f"[DEBUG edges] after tracking reload keys: {list(cr.keys())}")

            ge = cr.get("geodesic_edges") or {}
            has_e1 = isinstance(ge.get("edge1"), list) and len(ge.get("edge1")) > 1
            has_e2 = isinstance(ge.get("edge2"), list) and len(ge.get("edge2")) > 1

            # ✅ auto-detect if edge data lives under auto_best.normal_edge_points(_full)
            if not (has_e1 and has_e2):
                ab = cr.get("auto_best", {})
                for keyname in ("normal_edge_points_full", "normal_edge_points"):
                    if isinstance(ab.get(keyname), dict):
                        ne = ab[keyname]
                        e1 = ne.get("edge1", [])
                        e2 = ne.get("edge2", [])
                        if isinstance(e1, list) and len(e1) > 1 and isinstance(e2, list) and len(e2) > 1:
                            print(f"[DEBUG edges] recovered edges from auto_best.{keyname} (len={len(e1)})")
                            cr["geodesic_edges"] = {"edge1": e1, "edge2": e2}
                            set_geodesic_edges_for_crack(self.save_folder, base, crack_id, cr["geodesic_edges"])
                            #safe_write_json(p, cr)
                            safe_json_dump(cr, p)
                            has_e1 = has_e2 = True
                            break

            if not (has_e1 and has_e2):
                print(f"[edges] cid{crack_id}: still missing geodesic edges after tracking.")
                set_geodesic_edges_for_crack(self.save_folder, base, crack_id, ge)
                return False

        # --- Quick GT preview plot (mask + midline + geodesics visible) ---
        try:
            H, W = self.original_image.shape[:2]
            mask_bin = (self.current_mask > 0).astype(np.uint8)
            e1_xy = np.asarray(cr["geodesic_edges"].get("edge1", []), float)
            e2_xy = np.asarray(cr["geodesic_edges"].get("edge2", []), float)
            out_png = os.path.join(
                metric_image_dir(self.save_folder, base), f"cid{crack_id}", "gt_preview.png"
            )
            debug_plot_gt_preview(
                mask_bin, mid, e1_xy, e2_xy, out_png, title=f"GT/edges — cid{crack_id}"
            )
            print(f"[DEBUG edges] wrote GT preview: {out_png}")
        except Exception as e:
            print(f"[edges] cid{crack_id}: GT preview failed: {e}")
            traceback.print_exc()

        print(f"[DEBUG edges] ===== END ensure_tracked_edges_and_normals(cid={crack_id}) =====\n")
        return True
    
    # ---- 6) Auto variants generation (SAVE ONLY TO PER-CRACK FILES) --------------
    # ---------- crack_tool.py (REPLACE the whole function) ----------

    def generate_auto_variants_for_manual_parallel(
            self, crack_id, g_variants=None, cache_key=None, force_recompute=True,
            cpu_max_workers=None, color_channel=None, edge_params_fixed=None
        ):
        """
        Stores variants + best directly under the crack's snapshot file (flat),
        returns {"variants": {...}, "best_variant_id": int, "best": dict}.
        """
        import os, numpy as np, pandas as pd, cv2, traceback, math
        from rs3_split import run_rs3_variants_split, _variant_desc, plot_midlines_overlay_all
        from edge_workers import edge_param_worker
        from helpers.metrics import (
            set_auto_variant_for_crack, metric_atomic_path_for,
            safe_read_json, safe_write_json, metric_image_dir
        )

        base_name = self._image_base()
        p_cr = metric_atomic_path_for(self.save_folder, base_name, crack_id)
        crack = safe_read_json(p_cr, {})
        if not crack:
            print(f"[AUTO {crack_id}] ❌ per-crack snapshot not found"); return None
        src = (crack.get("source") or "").lower()
        if src.startswith("auto") or src == "combined":
            print(f"[AUTO {crack_id}] skip non-manual"); return None

        x, y, w, h = map(int, crack.get("mask_bbox", [0,0,0,0]))
        if w <= 0 or h <= 0:
            print(f"[AUTO {crack_id}] no bbox"); return None
        xmin, ymin, xmax, ymax = x, y, x + w, y + h

        man_xy_g = np.asarray(crack.get("midline", []), float)
        if man_xy_g.ndim != 2 or man_xy_g.shape[1] != 2 or len(man_xy_g) < 2:
            print(f"[AUTO {crack_id}] no manual midline"); return None
        p0, p1 = np.array(man_xy_g[0], float), np.array(man_xy_g[-1], float)

        # crop/cost prep
        try:
            self.active_bbox = [xmin, ymin, xmax, ymax]
            self.pts = [p0.copy(), p1.copy()]
            self.end_points = self.pts
            self.update_image_crop()
            self.update_os()
            self.update_cost()
            os_cost = self.costFunction
        except Exception as e:
            traceback.print_exc()
            print(f"[AUTO {crack_id}] ❌ OS/COST stage failed: {e}")
            return None

        down = self.downsample_factor_box.value() if hasattr(self,"downsample_factor_box") else getattr(self,"down",1) or 1
        p0_down_xy = np.asarray(self.pts_crop_down[0], float)
        p1_down_xy = np.asarray(self.pts_crop_down[1], float)

        if g_variants is None:
            vals = (25, 50, 75)
            g_variants = [{"g11":1.0, "g22":v, "g33":v} for v in vals]
            g_variants += [{"g11":1.0, "g22":25, "g33":35}, {"g11":1.0, "g22":35, "g33":25}]

        fm_results = run_rs3_variants_split(
            ct=__import__('cracktools'), os_cost=os_cost, p0_down_xy=p0_down_xy, p1_down_xy=p1_down_xy,
            g_variants=g_variants, down=int(down), bbox_xyxy=[xmin, ymin, xmax, ymax],
            cpu_max_workers=cpu_max_workers or min(os.cpu_count() or 8, 16), mp_start_method="spawn"
        )

        if color_channel is None:
            color_channel = (0 if self.edge_track_color_box.currentText() == "R"
                            else 1 if self.edge_track_color_box.currentText() == "B"
                            else 2)
        gray = self.image_crop[:, :, color_channel].astype(np.float32)
        pts_crop = self.pts_crop
        if edge_params_fixed is None:
            edge_params_fixed = {"window_half_size":45,"mu":0,"l":5,"p":14}

        base_payload = dict(
            image_crop_gray=gray, pts_crop=pts_crop,
            manual_midline_global=man_xy_g, auto_midline_global=None,
            bbox=(x, y, w, h), manual_normals_crop=None,
            params=edge_params_fixed,
        )

        crack_dir = os.path.join(self._metrics_dir(), f"cid{crack_id}")
        os.makedirs(crack_dir, exist_ok=True)

        variants_out, metrics_rows = {}, {}
        var_local_xy_by_id, variant_labels_by_id = {}, {}

        man_xy_crop = np.column_stack([man_xy_g[:,0]-x, man_xy_g[:,1]-y])

        for vid, r in enumerate(fm_results):
            if not r.get("ok"): 
                print(f"[AUTO {crack_id}] v{vid} ❌ {r.get('error')}"); 
                continue

            track_xy = np.asarray(r["track_full_xy"], float).T
            d0 = np.linalg.norm(track_xy[0] - p0); d1 = np.linalg.norm(track_xy[0] - p1)
            if d1 < d0: track_xy = track_xy[::-1]
            track_xy = track_xy + (p0 - track_xy[0])

            track_local_yx = np.vstack([track_xy[:,1]-y, track_xy[:,0]-x])
            track_crop_xy  = np.column_stack([track_xy[:,0]-x, track_xy[:,1]-y])

            payload = dict(base_payload); payload["adjusted_track"] = track_local_yx
            ew = edge_param_worker(payload)

            desc = _variant_desc(vid, g_variants[vid], edge_params_fixed)
            variant_labels_by_id[vid] = desc["label"]

            # flat vrec
            vrec = {"midline": track_xy.tolist(), "mask_bbox":[x,y,w,h], "params": desc}
            v_scores = {}
            if ew and isinstance(ew, dict):
                for k in ("normal_edge_points_full","normal_edge_points"):
                    if k in ew and ew[k]: 
                        vrec[k] = ew[k]
                if ew.get("status") == "ok":
                    v_scores = {k: float(ew[k]) for k in ("chamfer_mean","hausdorff","coverage") if k in ew}
                    row = dict(ew)
                    row.update({
                        "image": base_name, "crack_id": crack_id, "variant_id": vid,
                        **{k: desc[k] for k in ("g11","g22","g33","win","mu","ell","p")}
                    })
                    metrics_rows[vid] = row

            variants_out[f"v{vid}"] = vrec
            var_local_xy_by_id[vid] = track_crop_xy

            # persist flat variant (also writes auto_best later)
            set_auto_variant_for_crack(self.save_folder, base_name, crack_id, vrec, params=desc, is_best=False, scores=v_scores)

            print(f"[AUTO {crack_id}] v{vid} len={len(track_xy)} startΔ={np.linalg.norm(track_xy[0]-p0):.2f} "
                f"endΔ={np.linalg.norm(track_xy[-1]-p1):.2f}")

        # choose best (by scores, smaller chamfer/hausdorff, larger coverage)
        best_variant_id, best_flat = None, None
        if metrics_rows:
            df = pd.DataFrame(list(metrics_rows.values()))
            df = df.sort_values(["chamfer_mean","hausdorff","coverage"], ascending=[True,True,False])
            best_variant_id = int(df.iloc[0]["variant_id"])
            df.to_csv(os.path.join(crack_dir, "rs3_variants.csv"), index=False)

            import matplotlib.pyplot as plt
            plt.figure(figsize=(6,3))
            plt.bar(df["variant_id"].astype(str), df["chamfer_mean"])
            plt.title(f"Chamfer by variant — {base_name} cid{crack_id}")
            plt.xlabel("variant"); plt.ylabel("chamfer_mean")
            plt.tight_layout()
            plt.savefig(os.path.join(crack_dir, "chamfer_by_variant.png"), dpi=160); plt.close()

        if best_variant_id is not None and f"v{best_variant_id}" in variants_out:
            best_rec = variants_out[f"v{best_variant_id}"]
            best_flat = set_auto_variant_for_crack(
                self.save_folder, base_name, crack_id,
                best_rec, params=best_rec.get("params"), is_best=True
            )["auto_best"]

        # overlays
        crop_rgb = self.image_crop.copy()
        if crop_rgb.ndim == 2: crop_rgb = cv2.cvtColor(crop_rgb, cv2.COLOR_GRAY2BGR)
        im_overlay = crop_rgb.copy()
        if len(man_xy_crop) >= 2:
            pts = np.round(man_xy_crop).astype(np.int32).reshape(-1,1,2)
            cv2.polylines(im_overlay, [pts], False, (0,0,0), 5, lineType=cv2.LINE_AA)
            cv2.polylines(im_overlay, [pts], False, (255,255,255), 2, lineType=cv2.LINE_AA)
        color_cycle = ["#e41a1c","#377eb8","#4daf4a","#984ea3","#ff7f00","#a65628","#f781bf","#999999","#1b9e77","#d95f02"]
        for i,(vid, xy) in enumerate(sorted(var_local_xy_by_id.items())):
            if xy is None or len(xy) < 2: continue
            col = color_cycle[i % len(color_cycle)]
            bgr = tuple(int(col.lstrip("#")[j:j+2], 16) for j in (4,2,0))
            pts = np.round(xy).astype(np.int32).reshape(-1,1,2)
            cv2.polylines(im_overlay, [pts], False, bgr, 2, lineType=cv2.LINE_AA)
        cv2.imwrite(os.path.join(crack_dir, "midlines_overlay.png"), im_overlay)

        plot_midlines_overlay_all(
            image_crop_rgb=crop_rgb,
            man_local_xy=man_xy_crop,
            var_local_xy_by_id=var_local_xy_by_id,
            variant_labels_by_id=variant_labels_by_id,
            save_overlay_png=os.path.join(crack_dir, "midlines_overlay.png"),
            save_legend_png=os.path.join(crack_dir, "midlines_overlay_legend.png"),
        )

        # refresh in-memory snapshot cache
        from helpers.metrics import load_snapshot_from_files
        self.metric_annotations = load_snapshot_from_files(self.save_folder, base_name)

        print(f"[AUTO {crack_id}] ✅ {len(variants_out)} variants (best={best_variant_id})")
        return {"variants": variants_out, "best_variant_id": best_variant_id, "best": best_flat}
    

    # ---- 7) Combined auto masks from snapshot (REPLACE) --------------------------
    def _build_combined_auto_masks_same_indices(self, cache_key=None):
        """
        Build AUTO combined masks from per-crack auto_best + manual combined membership in snapshot.
        """
        import os, cv2, numpy as np, pandas as pd
        from helpers.metrics import _reconstruct_full_mask

        base_name = self._image_base()
        image_dir = self._metrics_dir()
        out_dir   = os.path.join(image_dir, "combined")
        os.makedirs(out_dir, exist_ok=True)

        self._sync_metrics_snapshot_from_authoring(refresh_combine=True, persist=True)
        ann = self.metric_annotations or {}
        atomic   = ann.get("atomic_cracks", {}) or {}
        combined = ann.get("combined_cracks", {}) or {}
        auto_best= ann.get("auto_best_atomic_cracks", {}) or {}

        if not combined: return
        H, W = self.original_image.shape[:2]
        rows = []

        for cmb_id, cmb in combined.items():
            members = cmb.get("members", []) or []
            if not members: continue

            m_manual = _reconstruct_full_mask(cmb, H, W)

            m_auto = np.zeros((H, W), np.uint8)
            for mid in members:
                best = auto_best.get(str(mid))
                if not best: continue
                mm = _reconstruct_full_mask(best, H, W)
                if mm is not None:
                    m_auto |= (mm > 0).astype(np.uint8)

            cv2.imwrite(os.path.join(out_dir, f"combined_{cmb_id}_manual.png"),
                        (m_manual>0).astype(np.uint8)*255)
            cv2.imwrite(os.path.join(out_dir, f"combined_{cmb_id}_auto.png"),
                        (m_auto>0).astype(np.uint8)*255)

            row = {"image": base_name, "combined_id": cmb_id}
            if getattr(self, "current_mask", None) is not None:
                from helpers.metrics import mask_iou
                row["iou_manual_vs_gt"] = mask_iou(m_manual, self.current_mask)
                row["iou_auto_vs_gt"]   = mask_iou(m_auto,   self.current_mask)
            rows.append(row)

        if rows:
            pd.DataFrame(rows).to_csv(os.path.join(out_dir, "combined_metrics.csv"), index=False)
            print(f"[combined] wrote → {os.path.join(out_dir, 'combined_metrics.csv')}")

    # ---- 8) Quick metrics driver (uses snapshot everywhere) ----------------------
    def run_metrics_on_current_image_quick(
        self, edge_grid=None, g_variants=None, cpu_max_workers=8, do_edge_calibrate=False
    ):
        """
        Fast iteration using the snapshot layer only. Keeps your timing logs.
        """
        import os, time, numpy as np, pandas as pd

        if getattr(self, "original_image", None) is None:
            print("[quick] no image loaded"); return {}
            
        # 2) Skip if JSON exists but has no manual midlines with ≥2 points

        base_name = self._image_base()
        print(f"\n[quick] metrics for current image: {base_name}")
        
        # --- SAFETY: if current in-memory annotation has no valid manual midlines, skip + purge snapshot ---
        ann = (getattr(self, "annotation", {}) or {}).get("annotations", {}) or {}
        atomic = ann.get("atomic_cracks", {}) or {}

        def _has_valid_manual_midlines(atomic_dict):
            for crack in atomic_dict.values():
                src = (crack.get("source") or "").lower()
                if src.startswith("auto") or src == "combined":
                    continue
                mid = crack.get("midline", [])
                if isinstance(mid, list) and len(mid) >= 2:
                    return True
            return False

        if not atomic or not _has_valid_manual_midlines(atomic):
            print(f"[DEBUG QUICK] 🧹 No valid manual midlines found in annotation — purging snapshot for {base_name}")
            import os

            # --- Construct per-image metrics snapshot path (where _metric_atomic() reads from)
            metrics_dir = os.path.join(self.save_folder, "metrics")
            snap_path = os.path.join(metrics_dir, f"{base_name}.json")

            if os.path.exists(snap_path):
                try:
                    os.remove(snap_path)
                    print(f"[DEBUG QUICK] Removed stale metrics snapshot: {snap_path}")
                except Exception as e:
                    print(f"[DEBUG QUICK] ⚠ Failed to remove {snap_path}: {e}")

            # also clear in-memory metric_annotations if loaded
            if hasattr(self, "metric_annotations"):
                self.metric_annotations.clear()
                print("[DEBUG QUICK] Cleared in-memory metric_annotations")

            return {}
        
        image_dir = self._metrics_dir()
        os.makedirs(image_dir, exist_ok=True)

        t_total_start = time.perf_counter()

        # Edge calibration (optional). We still use the worker + snapshot payloads.
        t_edge_start = time.perf_counter()
        if edge_grid is None:
            edge_grid = {"window_half_size":[35,45,55],"mu":[0,5],"l":[2,5],"p":[6,14]}
        best_edge = {"window_half_size":45,"mu":0.0,"l":5,"p":14}
        if do_edge_calibrate:
            rows = []
            # ensure snapshot exists
            self._sync_metrics_snapshot_from_authoring(refresh_combine=False, persist=True)
            for cid, cr in self._metric_atomic().items():
                src = (cr.get("source") or "").lower()
                if src.startswith("auto") or src == "combined": continue
                man_xy = np.asarray(cr.get("midline", []), float)
                if man_xy.ndim != 2 or man_xy.shape[1] != 2 or len(man_xy) < 2: continue
                df = self.sweep_edges_with_executor(cid, grid=edge_grid, max_workers=cpu_max_workers)
                if df is not None and not df.empty: rows.append(df)

            if rows:
                df = pd.concat(rows, ignore_index=True)
                param_cols = ["param_window_half_size","param_mu","param_l","param_p"]
                sub = df[[c for c in (param_cols+["chamfer_mean","hausdorff","coverage"]) if c in df.columns]].dropna()
                g = (sub.groupby(param_cols, as_index=False)
                        .agg({"chamfer_mean":"mean","hausdorff":"mean","coverage":"mean"}))
                g = g.sort_values(["chamfer_mean","hausdorff","coverage"], ascending=[True,True,False])
                row = g.iloc[0].to_dict()
                best_edge = {"window_half_size":int(row["param_window_half_size"]),
                            "mu":float(row["param_mu"]), "l":int(row["param_l"]), "p":int(row["param_p"])}
        t_edge_calib = time.perf_counter() - t_edge_start

        # Ensure tracked edges exist for manual cracks (snapshot write)
        '''need_ids = []
        for cid, cr in self._metric_atomic().items():
            src = (cr.get("source") or "").lower()
            if src.startswith("auto") or src == "combined": continue
            mid = np.asarray(cr.get("midline", []), float)
            if mid.ndim != 2 or mid.shape[1] != 2 or len(mid) < 2: continue
            ge = cr.get("geodesic_edges", {}) or {}
            has_e1 = isinstance(ge.get("edge1"), list) and len(ge.get("edge1")) > 1
            has_e2 = isinstance(ge.get("edge2"), list) and len(ge.get("edge2")) > 1
            has_mask = cr.get("mask_crop") is not None
            if not (has_e1 and has_e2 and has_mask): need_ids.append(cid)
        if need_ids:
            try:
                t_edgegen_start = time.perf_counter()
                _ = self.run_edge_tracking_parallel(crack_ids=need_ids, cpu_max_workers=cpu_max_workers, edge_params_fixed=best_edge)
                t_edgegen = time.perf_counter() - t_edgegen_start
                print(f"[quick] edge-tracking for {len(need_ids)} manual cracks took {t_edgegen:.2f}s")
            except Exception as e:
                print(f"[quick] manual edge-tracking failed: {e}")'''
                # ---------- Ensure tracked edges exist for manual cracks (snapshot write) ----------
        import numpy as np, time
        from helpers.metrics import metric_atomic_path_for, safe_read_json
        print("[DEBUG QUICK] verifying tracked edges + masks for all manual cracks...")

        need_ids = []
        for cid, cr in self._metric_atomic().items():
            src = (cr.get("source") or "").lower()
            if src.startswith("auto") or src == "combined":
                continue

            mid = np.asarray(cr.get("midline", []), float)
            if mid.ndim != 2 or mid.shape[1] != 2 or len(mid) < 2:
                continue

            ge = cr.get("geodesic_edges", {}) or {}
            has_e1 = isinstance(ge.get("edge1"), list) and len(ge.get("edge1")) > 1
            has_e2 = isinstance(ge.get("edge2"), list) and len(ge.get("edge2")) > 1
            has_mask = cr.get("mask_crop") is not None

            if not (has_e1 and has_e2 and has_mask):
                need_ids.append(cid)

        print(f"[DEBUG QUICK] cracks needing edge tracking: {need_ids}")
        if need_ids:
            try:
                t_edgegen_start = time.perf_counter()
                for cid in need_ids:
                    try:
                        print(f"[DEBUG QUICK] generating edges for cid={cid} ...")
                        ok = self.ensure_tracked_edges_and_normals(cid, best_edge)
                        if not ok:
                            print(f"[DEBUG QUICK] ❌ ensure_tracked_edges_and_normals failed for cid={cid}")
                    except Exception as e:
                        print(f"[DEBUG QUICK] ❌ edge gen inner fail for cid={cid}: {e}")
                t_edgegen = time.perf_counter() - t_edgegen_start
                print(f"[quick] edge-tracking for {len(need_ids)} manual cracks took {t_edgegen:.2f}s")
            except Exception as e:
                import traceback; traceback.print_exc()
                print(f"[quick] manual edge-tracking failed: {e}")

        # Auto variants per manual crack (snapshot write)
        t_auto_start = time.perf_counter()
        for cid, cr in self._metric_atomic().items():
            src = (cr.get("source") or "").lower()
            if src.startswith("auto") or src == "combined": continue
            man_xy = np.asarray(cr.get("midline", []), float)
            if man_xy.ndim != 2 or man_xy.shape[1] != 2 or len(man_xy) < 2: continue
            _ = self.generate_auto_variants_for_manual_parallel(
                crack_id=cid, g_variants=g_variants, edge_params_fixed=best_edge,
                cpu_max_workers=cpu_max_workers, force_recompute=True
            )
        t_auto_variants = time.perf_counter() - t_auto_start

        # Combined masks (snapshot read)
        t_mask_start = time.perf_counter()
        try:
            self._build_combined_auto_masks_same_indices(cache_key=None)
        except Exception as e:
            print(f"[quick] combined auto-mask build failed: {e}")
        t_mask_build = time.perf_counter() - t_mask_start

        # Mask & width metrics (snapshot read)
        t_mw_start = time.perf_counter()
        try:
            self.compute_mask_and_width_metrics_for_image(display=False, export_supervision=True)
        except Exception as e:
            print(f"[quick] mask/width stage failed: {e}")
        t_mask_width = time.perf_counter() - t_mw_start

        # (Optional) additional supervision export already done above

        total_time = time.perf_counter() - t_total_start

        # log timings
        log_path = os.path.join(image_dir, "runtime_log.csv")
        row = {
            "image": base_name,
            "edge_calibration_s": round(t_edge_calib, 2),
            "auto_variants_s": round(t_auto_variants, 2),
            "mask_build_s": round(t_mask_build, 2),
            "mask_width_s": round(t_mask_width, 2),
            "supervision_s": 0.0,
            "total_s": round(total_time, 2),
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
        }
        try:
            import pandas as pd
            if os.path.exists(log_path):
                df = pd.read_csv(log_path)
                df = pd.concat([df, pd.DataFrame([row])], ignore_index=True)
            else:
                df = pd.DataFrame([row])
            df.to_csv(log_path, index=False)
        except Exception as e:
            print(f"[quick] failed to write runtime_log.csv: {e}")

        print(f"[quick] ⏱ total = {total_time:.2f}s (edge={t_edge_calib:.2f}s, auto={t_auto_variants:.2f}s, "
            f"mask_build={t_mask_build:.2f}s, mask_width={t_mask_width:.2f}s)")
        return {"image": base_name, "best_edge": best_edge}

    # ---- 9) generate_auto_manual_midline (READ FROM SNAPSHOT VARIANTS) -----------
    def generate_auto_manual_midline(self, crack_id, cache_key=None, display=False):
        """
        Re-creates 'all autos vs manual' overlay reading ONLY per-crack snapshot variants.
        """
        import os, numpy as np, cv2, matplotlib.pyplot as plt
        from helpers.metrics import metric_atomic_path_for, safe_read_json
        base_name = self._image_base()
        p = metric_atomic_path_for(self.save_folder, base_name, crack_id)
        rec = safe_read_json(p, {})
        if not rec:
            print(f"[plot] crack {crack_id} not found in snapshot"); return

        x, y, w, h = map(int, rec.get("mask_bbox", [0,0,0,0]))
        self.active_bbox = [x, y, x+w, y+h]
        self.update_image_crop()
        crop_rgb = self.image_crop.copy()
        if crop_rgb.ndim == 2:
            crop_rgb = cv2.cvtColor(crop_rgb, cv2.COLOR_GRAY2BGR)

        man_xy = np.asarray(rec.get("midline", []), float)
        man_xy_crop = np.column_stack([man_xy[:,0]-x, man_xy[:,1]-y]) if len(man_xy)>=2 else np.empty((0,2))

        plt.figure(figsize=(6,6))
        plt.imshow(cv2.cvtColor(crop_rgb, cv2.COLOR_BGR2RGB))
        if len(man_xy_crop) >= 2:
            plt.plot(man_xy_crop[:,0], man_xy_crop[:,1], 'k-', lw=4, label="manual")
            plt.plot(man_xy_crop[:,0], man_xy_crop[:,1], 'w-', lw=2)

        colors = plt.cm.tab20.colors
        av = rec.get("auto_variants", []) or []
        for i, v in enumerate(av):
            auto = np.asarray(v.get("midline", []), float)
            if len(auto) < 2: continue
            auto_crop = np.column_stack([auto[:,0]-x, auto[:,1]-y])
            plt.plot(auto_crop[:,0], auto_crop[:,1], '-', lw=2, color=colors[i%len(colors)], label=f"v{i}")

        plt.legend(ncol=2, fontsize=8)
        plt.axis("equal"); plt.tight_layout()
        out_dir = os.path.join(self._metrics_dir(), f"cid{crack_id}")
        os.makedirs(out_dir, exist_ok=True)
        out_png = os.path.join(out_dir, "midlines_overlay_legend_replot.png")
        plt.savefig(out_png, dpi=180)
        if display: plt.show()
        else: plt.close()
        print(f"[plot] saved → {out_png}")

    
    
    
    
